/*
 * EngineData: CAN ID 0x100 (standard), 8 bytes, sender ECM, cycle time 10 ms
 * Engine status broadcast, 10 ms cycle.
 *
 * C struct generated by CanViewer from demo.dbc.
 * Each member holds the raw value of a signal; physical value = raw * factor + offset.
 */
#include <stdint.h>

#define ENGINEDATA_ID 0x100u
#define ENGINEDATA_IS_EXTENDED 0
#define ENGINEDATA_LENGTH 8u

typedef struct {
    /* start bit 0, 16 bits, Intel, unsigned, factor 0.25, offset 0, range 0 .. 16383.75 rpm */
    /* Crankshaft rotational speed. */
    uint16_t EngineSpeed;
    /* start bit 16, 8 bits, Intel, unsigned, factor 1, offset -40, range -40 .. 215 degC */
    uint8_t EngineTemp;
    /* start bit 24, 8 bits, Intel, unsigned, factor 0.4, offset 0, range 0 .. 100 % */
    uint8_t ThrottlePosition;
    /* start bit 32, 12 bits, Intel, unsigned, factor 0.5, offset 0, range 0 .. 2047.5 Nm */
    uint16_t EngineTorque;
    /* start bit 44, 12 bits, Intel, signed, factor 0.5, offset 0, range -1024 .. 1023.5 Nm */
    int16_t TorqueRequest;
    /* start bit 56, 1 bit, Intel, unsigned, factor 1, offset 0, range 0 .. 1 */
    uint8_t EngineRunning;
} EngineData_t;
